let size=fxrandBetween(300,500),angle=fxrandBetween(140,240);document.body.style.backgroundColor="hsl("+fxrandBetween(0,255)+", 20%, 20%)";let animate=1;function setup(){createCanvas(800,800,P2D),loop(),frameRate(60)}var colourA=fxrandBetween(0,255),colourB=fxrandBetween(0,255),colourC=fxrandBetween(0,255),count=0;function draw(){translate(width/2,height/2),count<fxrandBetween(5,20)&&(createFractal(size,angle,colourA,colourB,colourC),count++),1==animate&&(angle+=fxrandBetween(2,15))}function createFractal(size,angle,colourA,colourB,colourC){const controls={fractalA:fxrandBetween(0,5),fractalB:fxrandBetween(0,4),fractalC:fxrandBetween(10,500),fractalD:fxrandBetween(0,1),fractalE:fxrandBetween(0,2)};size>3&&(stroke(colourA,colourB,colourC),strokeWeight(map(controls.fractalA,controls.fractalB,controls.fractalC,controls.fractalD,controls.fractalE,!0)),push(),rotate(radians(angle)),line(0,0,size,0),translate(size,0),createFractal(size/2,angle),pop(),push(),rotate(radians(-angle)),line(0,0,size,0),translate(size,0),createFractal(size/2,angle),pop(),push(),rotate(radians(3*angle)),line(0,0,size,0),translate(size,0),createFractal(size/2,angle),pop())}function fxrandBetween(o,l){return fxrand()*(o-l)+l}